# Порядок документов в навигации внизу каждой страницы.
_DOC_NAV = [
    ("privacy", "Политика конфиденциальности"),
    ("terms", "Пользовательское соглашение"),
    ("refund", "Политика возврата"),
    ("rules", "Правила использования"),
    ("consent", "Согласие на обработку данных"),
]

_DOC_DATE = "Дата вступления в силу: 12 ноября 2026 г."


def _doc_page(kind: str) -> str:
    """Одна страница документа: политика, соглашение, возврат, правила, согласие."""
    p = _DOC_PAGES[kind]
    nav_docs = "".join(
        f'<a href="/{k}/">{label}</a>' for k, label in _DOC_NAV if k != kind
    )
    return f"""<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<meta name="theme-color" content="#020202">
<title>{p["title"]}</title>
<link rel="icon" href="{FAVICON_URL}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Unbounded:wght@500;600;700;800&display=swap" rel="stylesheet">
<style>{_DOC_PAGE_CSS}</style>
</head>
<body>
<div class="wrap">
  <div class="logo"><img src="{LOGO_URL}" alt="Drebol VPN"></div>
  <h1>{p["h1"]}</h1>
  <p class="date">{_DOC_DATE}</p>
  {p["body"]}
  <div class="nav">
    <a href="/">← На главную</a>
    <a href="/cabinet/">Кабинет</a>
    {nav_docs}
    <a href="{BOT_URL}">Открыть Telegram-бот</a>
  </div>
</div>
</body>
</html>
"""


def build_doc_pages() -> dict:
    """Документы Сервиса: {"privacy", "terms", "refund", "rules", "consent"}."""
    return {kind: _doc_page(kind) for kind in _DOC_PAGES}
